static int clamp50(int number)
{
    if (number < 0) {
        return 0;
    }
    if (number > 50) {
        return 50;
    }
    return number;
}

int main(void)
{
    printf("%d %d %d\n", clamp50(-5), clamp50(70), clamp50(50));
    return 0;
}

