#include <stdio.h>

static int bonus(int score)
{
    if (score >= 50) {
        return 5;
    }
    return 0;
}

static int check_bonus(int score, int expected)
{
    int actual = bonus(score);
    if (actual != expected) {
        printf("fail %d expected %d got %d\n", score, expected, actual);
        return 0;
    }

    printf("%d %d\n", score, actual);
    return 1;
}

int main(void)
{
    int passes = check_bonus(49, 0);
    passes += check_bonus(50, 5);
    passes += check_bonus(51, 5);
    printf("passed %d\n", passes);
    if (passes != 3) {
        return 1;
    }
    return 0;
}
